<?php
declare(strict_types=1);

final class BudgetController extends Controller
{
    public function index(): void
    {
        $user=$this->requireAuth();$stmt=$this->db->prepare('SELECT p.*,c.name AS clothing_name FROM purchases p LEFT JOIN clothes c ON c.id=p.clothing_id AND c.user_id=p.user_id WHERE p.user_id=:user_id ORDER BY p.purchased_at DESC,p.id DESC LIMIT 100');$stmt->execute(['user_id'=>$user['id']]);$purchases=$stmt->fetchAll();$stmt=$this->db->prepare('SELECT currency,SUM(amount) AS total FROM purchases WHERE user_id=:user_id GROUP BY currency ORDER BY currency');$stmt->execute(['user_id'=>$user['id']]);$totals=$stmt->fetchAll();$stmt=$this->db->prepare('SELECT currency,SUM(purchase_price) AS total FROM clothes WHERE user_id=:user_id AND purchase_price IS NOT NULL AND status<>\'archived\' GROUP BY currency ORDER BY currency');$stmt->execute(['user_id'=>$user['id']]);$wardrobe=$stmt->fetchAll();$stmt=$this->db->prepare('SELECT b.*,COALESCE(SUM(CASE WHEN p.currency=b.currency AND p.purchased_at BETWEEN b.period_start AND b.period_end THEN p.amount ELSE 0 END),0) AS spent FROM budgets b LEFT JOIN purchases p ON p.user_id=b.user_id AND p.purchased_at BETWEEN b.period_start AND b.period_end WHERE b.user_id=:user_id GROUP BY b.id ORDER BY b.period_start DESC');$stmt->execute(['user_id'=>$user['id']]);$budgets=$stmt->fetchAll();$stmt=$this->db->prepare('SELECT COALESCE(l.name,\'Autres dépenses\') AS category,p.currency,SUM(p.amount) AS total FROM purchases p LEFT JOIN clothes c ON c.id=p.clothing_id AND c.user_id=p.user_id LEFT JOIN clothing_labels l ON l.id=c.label_id WHERE p.user_id=:user_id AND p.purchased_at>=DATE_SUB(CURDATE(),INTERVAL 12 MONTH) GROUP BY category,p.currency ORDER BY p.currency,total DESC');$stmt->execute(['user_id'=>$user['id']]);$byCategory=$stmt->fetchAll();$rates=$this->db->prepare('SELECT * FROM exchange_rates WHERE user_id=:user_id ORDER BY effective_date DESC,id DESC LIMIT 12');$rates->execute(['user_id'=>$user['id']]);$clothes=$this->db->prepare('SELECT id,name FROM clothes WHERE user_id=:user_id ORDER BY name');$clothes->execute(['user_id'=>$user['id']]);render('budget/index',['title'=>'Budget et dépenses','purchases'=>$purchases,'totals'=>$totals,'wardrobe'=>$wardrobe,'budgets'=>$budgets,'byCategory'=>$byCategory,'rates'=>$rates->fetchAll(),'clothes'=>$clothes->fetchAll()]);
    }
    public function savePurchase(): void
    {
        $user=$this->requireAuth();if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);return;}verify_csrf();$name=trim((string)($_POST['item_name']??''));$clothing=(int)($_POST['clothing_id']??0);$amount=(string)($_POST['amount']??'');$currency=strtoupper(trim((string)($_POST['currency']??'USD')));$date=(string)($_POST['purchased_at']??date('Y-m-d'));$seller=trim((string)($_POST['seller']??''));$note=trim((string)($_POST['notes']??''));
        if($clothing){$stmt=$this->db->prepare('SELECT name FROM clothes WHERE id=:id AND user_id=:user_id');$stmt->execute(['id'=>$clothing,'user_id'=>$user['id']]);$clothingName=$stmt->fetchColumn();if(!$clothingName){flash('error','Vêtement inaccessible.');redirect('budget');}if($name==='')$name=$clothingName;}
        if($name===''||!is_numeric($amount)||(float)$amount<=0||!preg_match('/^[A-Z]{3}$/',$currency)||!$this->validDate($date)){flash('error','Vérifiez le nom, le montant positif, la devise et la date.');redirect('budget');}
        $this->db->prepare('INSERT INTO purchases(user_id,clothing_id,item_name,amount,currency,purchased_at,seller,notes) VALUES(:user_id,:clothing,:name,:amount,:currency,:date,:seller,:notes)')->execute(['user_id'=>$user['id'],'clothing'=>$clothing?:null,'name'=>$name,'amount'=>$amount,'currency'=>$currency,'date'=>$date,'seller'=>$seller?:null,'notes'=>$note?:null]);flash('success','Dépense enregistrée.');redirect('budget');
    }
    public function deletePurchase(): void
    {
        $user=$this->requireAuth();if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);return;}verify_csrf();$this->db->prepare('DELETE FROM purchases WHERE id=:id AND user_id=:user_id')->execute(['id'=>(int)($_POST['id']??0),'user_id'=>$user['id']]);flash('success','Dépense supprimée.');redirect('budget');
    }
    public function saveBudget(): void
    {
        $user=$this->requireAuth();if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);return;}verify_csrf();$name=trim((string)($_POST['name']??''));$amount=(string)($_POST['amount']??'');$currency=strtoupper(trim((string)($_POST['currency']??'USD')));$start=(string)($_POST['period_start']??'');$end=(string)($_POST['period_end']??'');if($name===''||!is_numeric($amount)||(float)$amount<=0||!preg_match('/^[A-Z]{3}$/',$currency)||!$this->validDate($start)||!$this->validDate($end)||$start>$end){flash('error','Vérifiez les informations du budget et ses dates.');redirect('budget');}$this->db->prepare('INSERT INTO budgets(user_id,name,amount,currency,period_start,period_end) VALUES(:user_id,:name,:amount,:currency,:start,:end)')->execute(['user_id'=>$user['id'],'name'=>$name,'amount'=>$amount,'currency'=>$currency,'start'=>$start,'end'=>$end]);flash('success','Budget ajouté.');redirect('budget');
    }
    public function saveExchange(): void
    {
        $user=$this->requireAuth();if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);return;}verify_csrf();$from=strtoupper(trim((string)($_POST['from_currency']??'')));$to=strtoupper(trim((string)($_POST['to_currency']??'')));$rate=(string)($_POST['rate']??'');$date=(string)($_POST['effective_date']??date('Y-m-d'));if(!preg_match('/^[A-Z]{3}$/',$from)||!preg_match('/^[A-Z]{3}$/',$to)||$from===$to||!is_numeric($rate)||(float)$rate<=0||!$this->validDate($date)){flash('error','Le taux doit être positif, entre deux devises différentes, avec une date valide.');redirect('budget');}$this->db->prepare('INSERT INTO exchange_rates(user_id,from_currency,to_currency,rate,effective_date) VALUES(:user_id,:from,:to,:rate,:date)')->execute(['user_id'=>$user['id'],'from'=>$from,'to'=>$to,'rate'=>$rate,'date'=>$date]);flash('success','Taux de change enregistré avec sa date.');redirect('budget');
    }
    private function validDate(string $date): bool{$d=DateTime::createFromFormat('!Y-m-d',$date);return $d!==false&&$d->format('Y-m-d')===$date;}
}
